import asyncio, re

async def read_all(path):
    text = ''
    offset = 0
    last = None
    for _ in range(40):
        r = await yuki_workspace_read({"path": path, "offset": offset})
        last = r
        if not r.get('ok'):
            return None, r
        d = r.get('data') or {}
        text += d.get('text') or ''
        nxt = d.get('next_offset')
        if not isinstance(nxt, int) or nxt <= offset:
            break
        offset = nxt
    return text, last

def to_num(s):
    s = s.strip()
    try:
        return int(s)
    except Exception:
        return float(s)

async def main():
    mtext, mrec = await read_all("/workspace/manifest.txt")
    if mtext is None:
        return {"stage": "manifest", "status": mrec.get('status'), "err": str(mrec.get('error'))[:300]}
    print("=== manifest.txt ===")
    print(mtext.strip())
    names = []
    seen = set()
    for tok in re.findall(r'[A-Za-z0-9_\-./]+\.csv', mtext):
        if tok not in seen:
            seen.add(tok); names.append(tok)
    print("LISTED CSV FILES:", len(names))

    recs = {}
    total_rows = 0
    bad = []
    hdr = None
    for n in names:
        p = n if n.startswith('/') else '/workspace/' + n.lstrip('./')
        t, r = await read_all(p)
        if t is None:
            bad.append((n, r.get('status'), str(r.get('error'))[:120])); continue
        lines = [ln for ln in t.replace('\r\n', '\n').split('\n') if ln.strip()]
        if not lines:
            bad.append((n, 'EMPTY', '')); continue
        cols = [c.strip().lower() for c in lines[0].split(',')]
        if hdr is None:
            hdr = cols
        def idx(*keys):
            for k in keys:
                if k in cols:
                    return cols.index(k)
            for i, c in enumerate(cols):
                for k in keys:
                    if k in c:
                        return i
            return None
        i_id, i_reg, i_amt, i_st = idx('id'), idx('region'), idx('amount'), idx('status', 'state')
        if None in (i_id, i_reg, i_amt, i_st):
            bad.append((n, 'COLS', str(cols))); continue
        for ln in lines[1:]:
            parts = [x.strip() for x in ln.split(',')]
            if len(parts) <= max(i_id, i_reg, i_amt, i_st):
                continue
            total_rows += 1
            rid = parts[i_id]
            if rid not in recs:
                recs[rid] = (parts[i_reg], to_num(parts[i_amt]), parts[i_st].lower())
    print("HEADER:", hdr)
    print("ROW COUNT:", total_rows, "UNIQUE IDS:", len(recs), "PROBLEMS:", bad)

    agg = {r: [0, 0] for r in ('A', 'B', 'C', 'D')}
    float_seen = False
    statuses = {}
    for rid, (reg, amt, st) in recs.items():
        statuses[st] = statuses.get(st, 0) + 1
        if st == 'ok' and reg in agg:
            agg[reg][0] += 1
            if isinstance(amt, float) and not amt.is_integer():
                float_seen = True
            agg[reg][1] += amt
    print("STATUSES:", statuses)

    def fmt(v):
        if isinstance(v, float) and v.is_integer():
            return str(int(v))
        return ("%g" % v) if isinstance(v, float) else str(v)

    tsv = "\n".join("%s\t%d\t%s" % (r, agg[r][0], fmt(agg[r][1])) for r in ('A', 'B', 'C', 'D')) + "\n"
    print("EXPECTED BATCH.TSV:")
    print(tsv, end='')

    w = await yuki_workspace_write({"path": "/workspace/batch.tsv", "text": tsv})
    print("WRITE ok=%s status=%s path=%s version=%s" % (w.get('ok'), w.get('status'), (w.get('data') or {}).get('path'), (w.get('data') or {}).get('version')))

    back, brec = await read_all("/workspace/batch.tsv")
    ok = (back == tsv)
    print("READBACK ok=%s status=%s exact_match=%s lines=%d" % (brec.get('ok'), brec.get('status'), ok, len(back.splitlines())))
    print("READBACK TEXT >>>")
    print(back, end='')
    print("<<<")
    return {"rows": total_rows, "unique": len(recs), "match": ok, "tsv": tsv}

r = asyncio.run(main())
print("RESULT:", r)
